#pragma once
#include <cstdint>
#include <cstddef>
#include <string>
#include <vector>
#include <cstring>

typedef uint8_t Byte;
typedef std::vector<Byte> ByteBuf;

static inline uint16_t Get16(const Byte* p) { return (uint16_t)(p[0] | (p[1] << 8)); }
static inline uint32_t Get32(const Byte* p) { return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24); }
static inline uint64_t Get64(const Byte* p) { uint64_t v = 0; for (int i = 7; i >= 0; i--) v = (v << 8) | p[i]; return v; }
static inline void Set16(Byte* p, uint16_t v) { p[0] = (Byte)v; p[1] = (Byte)(v >> 8); }
static inline void Set32(Byte* p, uint32_t v) { for (int i = 0; i < 4; i++) p[i] = (Byte)(v >> (8 * i)); }
static inline void Set64(Byte* p, uint64_t v) { for (int i = 0; i < 8; i++) p[i] = (Byte)(v >> (8 * i)); }

// Convert Unix time (seconds) to Windows FILETIME (100ns since 1601)
static inline uint64_t UnixToFileTime(uint64_t t) { return (t + 11644473600ULL) * 10000000ULL; }
static inline uint64_t FileTimeToUnix(uint64_t ft) { return ft / 10000000ULL - 11644473600ULL; }

bool ReadWholeFile(const std::string& path, ByteBuf& out);
bool WriteWholeFile(const std::string& path, const Byte* data, size_t size);
std::string FormatSizeKiB(uint64_t v); // "103102 bytes (101 KiB)"

