#pragma once
#include "Common.h"

// Streaming hash interface. All hashes uppercase-hex except where noted.
struct Hasher {
  virtual ~Hasher() {}
  virtual void Update(const Byte* data, size_t size) = 0;
  virtual size_t DigestSize() const = 0;
  virtual void Final(Byte* out) = 0; // writes DigestSize() bytes
};

Hasher* CreateCRC32();  // 4 bytes, poly 0xEDB88320 reflected
Hasher* CreateCRC64();  // 8 bytes, poly 0xC96C5795D7870F42 reflected (ECMA)
Hasher* CreateSHA1();   // 20 bytes
Hasher* CreateSHA256(); // 32 bytes
Hasher* CreateXXH64();  // 8 bytes, seed 0

std::string HexUpper(const Byte* data, size_t size);
std::string HexLower(const Byte* data, size_t size);

// convenience one-shot helpers returning hex strings
std::string CRC32Hex(const Byte* d, size_t n);   // upper
std::string SHA256Hex(const Byte* d, size_t n);  // LOWER (7z prints sha256/sha1 lowercase)
std::string SHA1Hex(const Byte* d, size_t n);    // lower
std::string XXH64Hex(const Byte* d, size_t n);   // upper
std::string CRC64Hex(const Byte* d, size_t n);   // upper
uint32_t CRC32Value(const Byte* d, size_t n);

