#pragma once
#include "Common.h"

// AES-256 CBC, single shot helpers. iv is 16 bytes.
void Aes256CbcEncrypt(const Byte key[32], const Byte iv[16], const Byte* in, Byte* out, size_t size); // size multiple of 16
void Aes256CbcDecrypt(const Byte key[32], const Byte iv[16], const Byte* in, Byte* out, size_t size);

// 7z AES key derivation (7zAES method id 06 F1 07 01).
// props: the coder properties blob from the archive (first byte: NumCyclesPower|salt/iv sizes).
// Derives 32-byte key and up-to-16-byte iv (rest zero).
// Returns false on malformed props.
bool SevenZipDeriveKey(const Byte* props, size_t propsSize, const std::string& password,
                       Byte key[32], Byte iv[16], uint32_t* numCyclesPowerOut = nullptr);

// Build 7zAES props blob and derive key for ENCRYPTION.
// numCyclesPower in [0..24], saltSize 0..16, ivSize 0..16 (7z uses e.g. cycles 19, salt 0..16, iv 16)
ByteBuf SevenZipMakeProps(uint32_t numCyclesPower, const Byte* salt, size_t saltSize,
                          const Byte* iv, size_t ivSize);
void SevenZipKeyFromPassword(uint32_t numCyclesPower, const Byte* salt, size_t saltSize,
                             const std::string& password, Byte key[32]);

