#pragma once
#include "Common.h"

struct LzmaProps {
  uint32_t dictSize = 1 << 20;
  int lc = 3, lp = 0, pb = 2;
  // encode/decode the 7z properties blob (1 props byte + 4-byte LE dict size)
  bool ParseProps(const Byte* p, size_t size); // 5 bytes
  void WriteProps(Byte* out) const;            // 5 bytes
  Byte PropsByte() const { return (Byte)((pb * 5 + lp) * 9 + lc); }
};

// Raw LZMA stream decode. If outSize == (uint64_t)-1, decode until end-of-stream marker.
// inConsumed (optional) receives number of input bytes consumed.
// Returns false on data error.
bool LzmaDecode(const Byte* in, size_t inSize, Byte* out, uint64_t outSize,
                const LzmaProps& props, size_t* inConsumed = nullptr);

// Raw LZMA encode of in[0..inSize). Produces a stream WITHOUT end marker when
// writeEndMarker==false (unpack size known externally, 7z folder case).
// Must be a valid stream decodable by any LZMA decoder.
bool LzmaEncode(const Byte* in, size_t inSize, ByteBuf& out,
                const LzmaProps& props, bool writeEndMarker);

// LZMA2 chunk-stream decode. dictProp is the 1-byte LZMA2 dict-size property (0..40).
// outSize is exact uncompressed size. Returns false on error.
bool Lzma2Decode(const Byte* in, size_t inSize, Byte* out, uint64_t outSize, Byte dictProp);

// LZMA2 encode. dictProp as above. Chooses per-chunk compressed vs stored.
ByteBuf Lzma2Encode(const Byte* in, uint64_t inSize, const LzmaProps& props, Byte dictProp);

// smallest LZMA2 dict-size byte whose dict >= size (clamped to [0,40])
Byte Lzma2DictByteForSize(uint64_t size);

