8	  bool ParseProps(const Byte* p, size_t size); // 5 bytes
9	  void WriteProps(Byte* out) const;            // 5 bytes
10	  Byte PropsByte() const { return (Byte)((pb * 5 + lp) * 9 + lc); }
11	};
12	
13	// Raw LZMA stream decode. If outSize == (uint64_t)-1, decode until end-of-stream marker.
14	// inConsumed (optional) receives number of input bytes consumed.
