#include "Deflate.h"

// Raw DEFLATE (RFC1951) decoder: stored, fixed-Huffman and dynamic-Huffman blocks.

namespace {

struct BitReader {
  const Byte* p;
  const Byte* end;
  uint64_t acc = 0;   // bit buffer, next bit is LSB
  int nbits = 0;      // valid bits in acc
  bool overrun = false;

  void refill() {
    while (nbits <= 56 && p < end) {
      acc |= (uint64_t)*p++ << nbits;
      nbits += 8;
    }
  }
  // Read n bits (n <= 16). Zero-padded past end of input (overrun flag set).
  unsigned get(unsigned n) {
    if (nbits < (int)n) {
      refill();
      if (nbits < (int)n) overrun = true;
    }
    unsigned v = (unsigned)(acc & (((uint64_t)1 << n) - 1));
    acc >>= n;
    nbits -= (int)n;
    return v;
  }
  void alignByte() {
    int drop = nbits & 7;
    acc >>= drop;
    nbits -= drop;
  }
};

// Single-level Huffman decode table indexed by the next maxLen input bits.
// Entry = (symbol << 4) | codeLen; entry 0 = invalid code.
struct HTab {
  int maxLen = 0;
  std::vector<uint32_t> tab;
};

static bool BuildHTab(const uint8_t* lens, int n, HTab& t) {
  unsigned cnt[16] = {};
  for (int i = 0; i < n; i++) {
    if (lens[i] > 15) return false;
    cnt[lens[i]]++;
  }
  int maxLen = 15;
  while (maxLen > 0 && cnt[maxLen] == 0) maxLen--;
  if (maxLen == 0) { t.maxLen = 0; t.tab.clear(); return true; } // empty code set
  // check for over-subscription (incomplete codes are tolerated)
  int left = 1;
  for (int l = 1; l <= 15; l++) {
    left = (left << 1) - (int)cnt[l];
    if (left < 0) return false;
  }
  unsigned next[16];
  unsigned code = 0;
  for (int l = 1; l <= 15; l++) {
    code = (code + cnt[l - 1]) << 1;
    next[l] = code;
  }
  t.maxLen = maxLen;
  t.tab.assign((size_t)1 << maxLen, 0);
  for (int i = 0; i < n; i++) {
    int l = lens[i];
    if (!l) continue;
    unsigned c = next[l]++;
    unsigned rev = 0; // deflate stores codes MSB-first; table index is LSB-first
    for (int k = 0; k < l; k++) { rev = (rev << 1) | (c & 1); c >>= 1; }
    uint32_t e = ((uint32_t)i << 4) | (uint32_t)l;
    for (size_t idx = rev; idx < t.tab.size(); idx += (size_t)1 << l)
      t.tab[idx] = e;
  }
  return true;
}

static int DecSym(BitReader& br, const HTab& t) {
  if (t.maxLen == 0) return -1;
  br.refill();
  uint32_t e = t.tab[(size_t)(br.acc & (((uint64_t)1 << t.maxLen) - 1))];
  if (!e) return -1;
  int l = (int)(e & 15);
  if (br.nbits < l) br.overrun = true;
  br.acc >>= l;
  br.nbits -= l;
  return (int)(e >> 4);
}

static const uint16_t kLenBase[29] = {
  3, 4, 5, 6, 7, 8, 9, 10, 11, 13, 15, 17, 19, 23, 27, 31,
  35, 43, 51, 59, 67, 83, 99, 115, 131, 163, 195, 227, 258
