    BuildHTab(lens, 32, h);
    return h;
  }();
  return t;
}

static bool DecodeHuffBlock(BitReader& br, const HTab& lit, const HTab& dist,
                            Byte*& op, Byte* oend, Byte* out) {
  for (;;) {
    int s = DecSym(br, lit);
    if (s < 0) return false;
    if (s < 256) {
      if (op >= oend) return false;
      *op++ = (Byte)s;
    } else if (s == 256) {
      return true;
    } else {
      s -= 257;
      if (s >= 29) return false; // 286, 287 invalid
      unsigned len = kLenBase[s] + br.get(kLenExtra[s]);
      int ds = DecSym(br, dist);
      if (ds < 0 || ds >= 30) return false;
      unsigned d = kDistBase[ds] + br.get(kDistExtra[ds]);
      if (d == 0 || d > (unsigned)(op - out)) return false;
      if (len > (unsigned)(oend - op)) return false;
      const Byte* m = op - d;
      if (d >= len) {
        memcpy(op, m, len);
        op += len;
      } else {
        for (unsigned k = 0; k < len; k++) *op++ = *m++;
      }
    }
  }
}

} // namespace

bool InflateRaw(const Byte* in, size_t inSize, Byte* out, size_t outSize, size_t* inConsumed) {
