      unsigned hdist = br.get(5) + 1;
      unsigned hclen = br.get(4) + 4;
      if (hlit > 288 || hdist > 32) return false;
      static const uint8_t kOrder[19] = {
        16, 17, 18, 0, 8, 7, 9, 6, 10, 5, 11, 4, 12, 3, 13, 2, 14, 1, 15
      };
      uint8_t clLens[19] = {};
      for (unsigned i = 0; i < hclen; i++) clLens[kOrder[i]] = (uint8_t)br.get(3);
