      if (!BuildHTab(clLens, 19, clTab)) return false;
      uint8_t lens[288 + 32];
      unsigned total = hlit + hdist;
      unsigned i = 0;
      while (i < total) {
        int s = DecSym(br, clTab);
        if (s < 0) return false;
        if (s < 16) {
          lens[i++] = (uint8_t)s;
        } else if (s == 16) {
          if (i == 0) return false;
          unsigned rep = 3 + br.get(2);
          if (i + rep > total) return false;
          uint8_t prev = lens[i - 1];
          while (rep--) lens[i++] = prev;
        } else if (s == 17) {
          unsigned rep = 3 + br.get(3);
          if (i + rep > total) return false;
          while (rep--) lens[i++] = 0;
        } else { // 18
          unsigned rep = 11 + br.get(7);
          if (i + rep > total) return false;
          while (rep--) lens[i++] = 0;
        }
      }
      if (lens[256] == 0) return false; // no end-of-block code
      HTab litTab, distTab;
      if (!BuildHTab(lens, (int)hlit, litTab)) return false;
      if (!BuildHTab(lens + hlit, (int)hdist, distTab)) return false;
      if (!DecodeHuffBlock(br, litTab, distTab, op, oend, out)) return false;
