  if (op != oend) return false; // exact output size required
  if (inConsumed) {
    size_t bitsUsed = 8 * (size_t)(br.p - in) - (size_t)(br.nbits > 0 ? br.nbits : 0);
    *inConsumed = (bitsUsed + 7) / 8;
  }
  return true;
}

