#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <sys/stat.h>
#include "../src/Common.h"
#include "../src/Deflate.h"

static int fails = 0;
#define CHECK(cond, msg) do { if (!(cond)) { printf("FAIL: %s\n", msg); fails++; } } while (0)

static bool ReadFile(const std::string& p, ByteBuf& b) {
  FILE* f = fopen(p.c_str(), "rb");
  if (!f) return false;
  fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);
  b.resize(sz);
  bool ok = sz == 0 || fread(b.data(), 1, sz, f) == (size_t)sz;
  fclose(f);
  return ok;
}

static void Roundtrip(const std::string& name, const ByteBuf& data) {
  for (int lvl : {0, 1, 9}) {
    ByteBuf comp = DeflateRaw(data.data(), data.size(), lvl);
    ByteBuf back(data.size());
    size_t consumed = 0;
    bool ok = InflateRaw(comp.data(), comp.size(), back.data(), back.size(), &consumed);
    char msg[256];
    snprintf(msg, sizeof msg, "%s level %d inflate ok (comp=%zu orig=%zu)", name.c_str(), lvl, comp.size(), data.size());
    CHECK(ok, msg);
    if (ok) {
      snprintf(msg, sizeof msg, "%s level %d content match", name.c_str(), lvl);
      CHECK(back == data, msg);
      snprintf(msg, sizeof msg, "%s level %d consumed=%zu <= comp.size=%zu", name.c_str(), lvl, consumed, comp.size());
      CHECK(consumed <= comp.size() && consumed + 1 >= comp.size(), msg);
    }
  }
}

int main() {
  // (a) roundtrips
  const char* files[] = {"work/empty.bin", "work/zeros.bin", "work/rand.bin", "work/a.txt", "work/hello.txt"};
  for (const char* f : files) {
    ByteBuf d;
    if (!ReadFile(f, d)) { printf("skip %s\n", f); continue; }
    Roundtrip(f, d);
  }
  // 1MB generated text
  ByteBuf text;
  {
    const char* words[] = {"the ", "quick ", "brown ", "fox ", "jumps ", "over ", "lazy ", "dog. ",
                           "Lorem ", "ipsum ", "dolor ", "sit ", "amet, ", "consectetur\n", "7zip ", "deflate "};
    unsigned s = 12345;
    while (text.size() < (1u << 20)) {
      s = s * 1103515245 + 12345;
      const char* w = words[(s >> 16) % 16];
      text.insert(text.end(), w, w + strlen(w));
    }
    WriteFile("/tmp/text1m.bin", text);
    Roundtrip("/tmp/text1m.bin", text);
  }

  // (b) parse work/arc.zip, inflate method-8 entries, compare to work/ files
  {
    ByteBuf z;
    CHECK(ReadFile("work/arc.zip", z), "read arc.zip");
    // find EOCD
    size_t eocd = 0; bool found = false;
    for (size_t i = z.size() >= 22 ? z.size() - 22 : 0;; i--) {
      if (Get32(z.data() + i) == 0x06054b50) { eocd = i; found = true; break; }
      if (i == 0) break;
    }
    CHECK(found, "EOCD found");
    if (found) {
      unsigned nent = Get16(z.data() + eocd + 10);
      size_t cd = Get32(z.data() + eocd + 16);
      int zipChecked = 0;
      for (unsigned e = 0; e < nent; e++) {
        CHECK(Get32(z.data() + cd) == 0x02014b50, "central sig");
        unsigned method = Get16(z.data() + cd + 10);
        unsigned csize = Get32(z.data() + cd + 20);
        unsigned usize = Get32(z.data() + cd + 24);
        unsigned nlen = Get16(z.data() + cd + 28);
        unsigned elen = Get16(z.data() + cd + 30);
        unsigned clen = Get16(z.data() + cd + 32);
        unsigned lho = Get32(z.data() + cd + 42);
        std::string name((const char*)z.data() + cd + 46, nlen);
        size_t lh = lho;
        CHECK(Get32(z.data() + lh) == 0x04034b50, "local sig");
        unsigned lnlen = Get16(z.data() + lh + 26);
        unsigned lelen = Get16(z.data() + lh + 28);
        const Byte* cdata = z.data() + lh + 30 + lnlen + lelen;
        printf("zip entry: %s method=%u csize=%u usize=%u\n", name.c_str(), method, csize, usize);
        if (method == 8 && !name.empty() && name.back() != '/') {
          ByteBuf outb(usize);
          size_t consumed = 0;
          bool ok = InflateRaw(cdata, csize, outb.data(), usize, &consumed);
          char msg[300];
          snprintf(msg, sizeof msg, "inflate zip entry %s", name.c_str());
          CHECK(ok, msg);
          if (ok) {
            snprintf(msg, sizeof msg, "consumed==csize for %s (%zu vs %u)", name.c_str(), consumed, csize);
            CHECK(consumed == csize, msg);
            std::string origPath = std::string("work/") + name;
            ByteBuf orig;
            if (ReadFile(origPath, orig)) {
              snprintf(msg, sizeof msg, "zip entry %s matches work file", name.c_str());
              CHECK(outb == orig, msg);
              zipChecked++;
            } else {
              printf("  (no work/%s to compare)\n", name.c_str());
            }
          }
        }
        cd += 46 + nlen + elen + clen;
      }
      CHECK(zipChecked > 0, "at least one zip entry verified");
    }
  }

  // (c) gzip wrapper around our DeflateRaw, tested with real 7-Zip
  {
    ByteBuf orig;
    CHECK(ReadFile("/tmp/text1m.bin", orig), "read text1m");
    for (int lvl : {0, 1, 9}) {
      ByteBuf comp = DeflateRaw(orig.data(), orig.size(), lvl);
      ByteBuf gz;
      Byte hdr[10] = {0x1F, 0x8B, 0x08, 0, 0, 0, 0, 0, 0, 3};
      gz.insert(gz.end(), hdr, hdr + 10);
      gz.insert(gz.end(), comp.begin(), comp.end());
      // CRC32
      static uint32_t tab[256];
      static bool init = false;
      if (!init) {
        for (int i = 0; i < 256; i++) {
          uint32_t c = i;
          for (int k = 0; k < 8; k++) c = (c & 1) ? 0xEDB88320u ^ (c >> 1) : c >> 1;
          tab[i] = c;
        }
        init = true;
      }
      uint32_t crc = 0xFFFFFFFFu;
      for (Byte b : orig) crc = tab[(crc ^ b) & 0xFF] ^ (crc >> 8);
      crc ^= 0xFFFFFFFFu;
      Byte tail[8];
      Set32(tail, crc);
      Set32(tail + 4, (uint32_t)orig.size());
      gz.insert(gz.end(), tail, tail + 8);
      char path[64];
      snprintf(path, sizeof path, "/tmp/test%d.gz", lvl);
      WriteFile(path, gz);
      char cmd[256];
      snprintf(cmd, sizeof cmd, "cd work && ../executable t %s >/dev/null 2>&1", path);
      int rc = system(cmd);
      char msg[128];
      snprintf(msg, sizeof msg, "7z t %s rc==0 (rc=%d)", path, rc);
      CHECK(rc == 0, msg);
      snprintf(cmd, sizeof cmd, "cd work && ../executable x %s -so 2>/dev/null | cmp - /tmp/text1m.bin", path);
      rc = system(cmd);
      snprintf(msg, sizeof msg, "7z x -so %s matches original (rc=%d)", path, rc);
      CHECK(rc == 0, msg);
    }
  }

  if (fails == 0) printf("ALL TESTS PASSED\n");
  else printf("%d FAILURES\n", fails);
  return fails ? 1 : 0;
}

static void WriteFile(const std::string& p, const ByteBuf& b) {
  FILE* f = fopen(p.c_str(), "wb");
  if (!b.empty()) fwrite(b.data(), 1, b.size(), f);
  fclose(f);
}

