1	// LZMA / LZMA2 decoder — original implementation from the LZMA format
2	// specification (range coder + adaptive binary probability models).
3	#include "Lzma.h"
4	#include <algorithm>
5	
6	namespace {
7	
8	constexpr uint32_t kTopValue       = 1u << 24;   // range coder renormalization threshold
9	constexpr int      kNumMoveBits    = 5;          // probability adaption shift
10	constexpr uint16_t kProbInit       = 1u << 10;   // 0.5 in 11-bit fixed point
11	constexpr int      kNumStates      = 12;
12	constexpr int      kNumPosBitsMax  = 4;
13	constexpr int      kMatchMinLen    = 2;
14	constexpr int      kEndPosModelOff = 14;
15	constexpr int      kNumAlignBits   = 4;
16	constexpr int      kNumLitContext  = 0x300;      // probs per literal context
17	
18	// ---------------------------------------------------------------- range coder
19	
20	class RangeDec {
21	public:
22	  const Byte* buf = nullptr;
23	  size_t size = 0, pos = 0;
24	  uint32_t range = 0, code = 0;
25	  bool error = false;
26	
27	  void Init(const Byte* b, size_t s) {
28	    buf = b; size = s; pos = 0;
29	    range = 0xFFFFFFFFu; code = 0; error = false;
30	    if (s < 5 || b[0] != 0) { error = true; return; }
31	    pos = 1;
32	    for (int i = 0; i < 4; i++)
33	      code = (code << 8) | buf[pos++];
34	  }
35	
36	  void Normalize() {
37	    if (range < kTopValue) {
38	      if (pos >= size) { error = true; return; }
39	      range <<= 8;
40	      code = (code << 8) | buf[pos++];
41	    }
42	  }
43	
44	  uint32_t DecodeBit(uint16_t& prob) {
45	    uint32_t bound = (range >> 11) * prob;
46	    uint32_t bit;
47	    if (code < bound) {
48	      range = bound;
49	      prob = (uint16_t)(prob + ((0x800u - prob) >> kNumMoveBits));
50	      bit = 0;
51	    } else {
52	      range -= bound;
53	      code -= bound;
54	      prob = (uint16_t)(prob - (prob >> kNumMoveBits));
55	      bit = 1;
56	    }
57	    Normalize();
58	    return bit;
59	  }
60	
61	  uint32_t DecodeDirectBits(int n) {
62	    uint32_t v = 0;
63	    while (n-- > 0) {
64	      range >>= 1;
65	      v <<= 1;
66	      if (code >= range) { code -= range; v |= 1; }
67	      Normalize();
68	    }
69	    return v;
70	  }
71	};
72	
73	static uint32_t BitTreeDecode(RangeDec& rc, uint16_t* probs, int numBits) {
74	  uint32_t m = 1;
75	  for (int i = 0; i < numBits; i++)
76	    m = (m << 1) | rc.DecodeBit(probs[m]);
77	  return m - (1u << numBits);
78	}
79	
80	static uint32_t BitTreeReverseDecode(RangeDec& rc, uint16_t* probs, int numBits) {
81	  uint32_t m = 1, v = 0;
82	  for (int i = 0; i < numBits; i++) {
83	    uint32_t b = rc.DecodeBit(probs[m]);
84	    m = (m << 1) | b;
85	    v |= b << i;
86	  }
87	  return v;
88	}
89	
90	// ------------------------------------------------------------- length coder
91	
92	struct LenCoder {
93	  uint16_t choice, choice2;
94	  uint16_t low[1 << kNumPosBitsMax][8];
95	  uint16_t mid[1 << kNumPosBitsMax][8];
96	  uint16_t high[256];
97	
98	  void Init() {
99	    choice = choice2 = kProbInit;
100	    std::fill(&low[0][0], &low[0][0] + (1 << kNumPosBitsMax) * 8, kProbInit);
101	    std::fill(&mid[0][0], &mid[0][0] + (1 << kNumPosBitsMax) * 8, kProbInit);
102	    std::fill(high, high + 256, kProbInit);
103	  }
104	
105	  // returns 0..(273-kMatchMinLen)
106	  uint32_t Decode(RangeDec& rc, uint32_t posState) {
107	    if (!rc.DecodeBit(choice))
108	      return BitTreeDecode(rc, low[posState], 3);
109	    if (!rc.DecodeBit(choice2))
110	      return 8 + BitTreeDecode(rc, mid[posState], 3);
111	    return 16 + BitTreeDecode(rc, high, 8);
112	  }
113	};
114	
115	// ------------------------------------------------------------------ decoder
116	
117	// Probability state + repetition history. The output window is the caller's
118	// buffer; positions for contexts (lp/pb) and distance checks are taken
119	// relative to winStart_, which moves only on a dictionary reset (LZMA2).
120	class LzmaDecoder {
121	public:
122	  bool SetProps(int lc, int lp, int pb) {
123	    if (lc < 0 || lc > 8 || lp < 0 || lp > 4 || pb < 0 || pb > 4)
124	      return false;
125	    lc_ = lc; lp_ = lp;
126	    lpMask_ = (1u << lp) - 1;
127	    pbMask_ = (1u << pb) - 1;
128	    lit_.assign(size_t(kNumLitContext) << (lc + lp), kProbInit);
129	    hasProps_ = true;
130	    return true;
131	  }
132	
133	  // Reset probabilities, state machine and rep distances. The output window
134	  // (and virtual position) is untouched, so LZMA2 chunks can continue.
135	  void ResetState() {
136	    state_ = 0;
137	    rep0_ = rep1_ = rep2_ = rep3_ = 1;
138	    std::fill(&isMatch_[0][0], &isMatch_[0][0] + kNumStates * (1 << kNumPosBitsMax), kProbInit);
139	    std::fill(isRep_, isRep_ + kNumStates, kProbInit);
140	    std::fill(isRepG0_, isRepG0_ + kNumStates, kProbInit);
141	    std::fill(isRepG1_, isRepG1_ + kNumStates, kProbInit);
142	    std::fill(isRepG2_, isRepG2_ + kNumStates, kProbInit);
143	    std::fill(&isRep0Long_[0][0], &isRep0Long_[0][0] + kNumStates * (1 << kNumPosBitsMax), kProbInit);
144	    std::fill(&posSlot_[0][0], &posSlot_[0][0] + 4 * 64, kProbInit);
145	    std::fill(specPos_, specPos_ + 128, kProbInit);
146	    std::fill(posAlign_, posAlign_ + 16, kProbInit);
147	    lenCoder_.Init();
148	    repLenCoder_.Init();
149	    if (hasProps_)
150	      std::fill(lit_.begin(), lit_.end(), kProbInit);
151	  }
152	
153	  void SetWindow(Byte* out, uint64_t outPos, uint64_t winStart) {
154	    out_ = out; outPos_ = outPos; winStart_ = winStart;
155	  }
156	
157	  // Decode raw LZMA symbols until either outCount bytes have been produced
158	  // or (only when allowMarker) an end-of-stream marker is reached.
159	  // Returns false on data error. *consumed / *produced are always set.
160	  bool Run(const Byte* in, size_t inSize, uint64_t outCount, bool allowMarker,
161	           size_t* consumed, uint64_t* produced) {
162	    if (!hasProps_) return false;
163	    RangeDec rc;
164	    rc.Init(in, inSize);
165	    uint64_t limit = outPos_ + outCount; // may wrap to -1: intended for unknown size
166	    if (outCount == UINT64_MAX) limit = UINT64_MAX;
167	    bool sawMarker = false;
168	    while (outPos_ < limit) {
169	      if (rc.error) return false;
170	      uint64_t rel = outPos_ - winStart_;
171	      uint32_t posState = (uint32_t)(rel & pbMask_);
172	
173	      if (!rc.DecodeBit(isMatch_[state_][posState])) {
174	        // ---- literal
175	        Byte prev = rel ? out_[outPos_ - 1] : (Byte)0;
176	        uint32_t ctx = ((uint32_t)(rel & lpMask_) << lc_) +
177	                       (lc_ ? (uint32_t)(prev >> (8 - lc_)) : 0u);
178	        uint16_t* probs = &lit_[size_t(kNumLitContext) * ctx];
179	        uint32_t sym = 1;
180	        if (state_ >= 7) {
181	          // matched-literal mode: use the byte at the current rep0 distance
182	          Byte matchByte = out_[outPos_ - rep0_ - 1];
183	          do {
184	            uint32_t matchBit = (matchByte >> 7) & 1;
185	            matchByte = (Byte)(matchByte << 1);
186	            uint32_t bit = rc.DecodeBit(probs[((1 + matchBit) << 8) + sym]);
187	            sym = (sym << 1) | bit;
188	            if (matchBit != bit) break;
189	          } while (sym < 0x100);
190	        }
191	        while (sym < 0x100)
192	          sym = (sym << 1) | rc.DecodeBit(probs[sym]);
193	        out_[outPos_++] = (Byte)sym;
194	        state_ = (state_ < 4) ? 0 : (state_ < 10 ? state_ - 3 : state_ - 6);
195	        continue;
196	      }
197	
198	      uint32_t len;
199	      if (rc.DecodeBit(isRep_[state_])) {
200	        // ---- repeated match
201	        if (!rc.DecodeBit(isRepG0_[state_])) {
202	          if (!rc.DecodeBit(isRep0Long_[state_][posState])) {
203	            // short rep: single byte at distance rep0+1
204	            state_ = state_ < 7 ? 9 : 11;
205	            if ((uint64_t)rep0_ + 1 > rel) return false;
206	            out_[outPos_] = out_[outPos_ - rep0_ - 1];
207	            outPos_++;
208	            continue;
209	          }
210	        } else {
211	          uint32_t dist;
